    bookImgUrl: "https://ireading.kh.edu.tw/manage/static/DataFiles/Product/PEF168992638762038.jpg",
    introduce: "在書中，作者挖了大大小小的洞當做窗子，聖誕老公公就是從窗口看看屋子裡住的是什麼小動物，才決定要送什麼禮物。然而，畢竟視覺也有意外與差錯的時候，所以，書中的情節充滿了遊戲般的樂趣與驚喜：聖誕老公公和我們一樣，也有看走眼和判斷錯誤的時候，因而發展出很多幽默風趣的情節來。聖誕老公公從窗口看到的明明是一隻熟睡的小貓，然而打開次頁的小讀者卻會發現，小貓只是小胖豬身上那件衣服的圖樣而己！出現在另一個窗口的是黑白相間的條紋，聖誕老公公認定這兒住的一定是斑馬。沒想到事實上卻是 三隻脖子又白又長的鳥兒，襯著黑色的牆壁而形成的視覺騙局呢！還有一個窗口，出現了兩個男孩並排的睡臉，所以聖誕老公公送給他們兩份禮物。然而真相是：只有一個男孩在睡覺，另一個是畫在汽球上的臉兒，聖誕老公公又被騙了。畫面上我們看到小男孩的房間裡有好多東西，從那些東西我們能猜到他是愛美勞、愛打棒球、愛觀察昆蟲的小小科學家呢！翻到最後一個跨頁，動物們都出現了，找找看，他們把聖誕公公送的禮物穿在哪兒、戴在哪兒或繫在哪兒？動物和禮物構築出了一個充滿童趣的天真畫面。欣賞過這一本精彩的洞洞書之後，小朋友也可以利用圖畫紙來製作一張有洞洞的圖畫，例如：樹洞裡有一隻小動物；房門或窗子一打開，就有什麼東西跑出來等等。一定很好玩喔！",
