    bookImgUrl: "https://ireading.kh.edu.tw/manage/static/DataFiles/Product/PEF168992638712240.jpg",
    introduce: "鱷魚的牙齒讓你想到什麼呢？公雞的紅雞冠讓你想到什麼呢？獅子的鼻子像什麼？蜻蜓的身體又像什麼呢？日本國際級的童書大師五味太郎每次看到鱷魚的牙齒，就忍不住想到牙刷，他將這一個小小的想像加以發揮，因此成就了《誰吃掉了？》、《藏在誰那兒呢？》這兩本饒富趣味的圖畫書。兩本書的句型都相當簡單，每翻一頁就以一個問句來挑戰小朋友的觀察力，如：「草莓被誰吃掉了？」「荷包蛋被誰吃掉了？」「蠟燭藏在誰那兒呢？」「鉛筆藏在誰那兒呢？」讓小朋友在不同的動物或人身上，找到那些被藏起來的東西。除了以「找找看」的方式來做觀察力的訓練外，五味太郎還在書中特別設計了「數數看」的趣味，從第一頁的2隻大象（公雞）到最後一頁的12個小朋友，隨著頁數的增加，同時增加了視覺辨識與數數兒的難度。",
