    introduce: "有智慧的爺爺，用巧手把孫子心愛的破毯子變成外套、背心、領帶、手帕、鈕扣。這是爺爺對孫子愛的表現，即使再破舊，約瑟也捨不得丟，他相信爺爺一定有辦法把舊東西變成新的東西。就這樣毯子最後成了鈕扣，而鈕扣弄丟了，再也沒辦法翻成新東西了，但約瑟卻從這個過程中，學到物品由舊變新的意義，也寫下了這個可以永久流傳且歷久彌新的故事。作者在圖中設計了一個隱藏，平行故事︰約瑟家木板底下的老鼠家庭正用爺爺剪下的餘布，做成家人的日用品；賦予舊東西新的意義──這也是這個故事的主要精神。",
