    bookImgUrl: "https://ireading.kh.edu.tw/manage/static/DataFiles/Product/PEF168992639372634.jpg",
    introduce: "鑽進鑽出、毛毛蟲忙得不得了，一個洞、二個洞、三個洞&hellip;&hellip;一口接一口、不停地吃吃吃，肥嘟嘟的，牠究竟什麼時候才吃飽？這隻毛毛蟲出自艾瑞．卡爾的筆下，拱著圓圓胖胖的身體，一路暢行無阻地從美國爬向全世界50多個國家，擁有超過3300萬個小書迷。這本經典洞洞書是許多寶寶的第一本圖畫書，有趣的洞洞設計，可以讓小小指頭可以在洞裡鑽進鑽出。艾瑞．卡爾運用獨特的拼貼技巧，讓色彩不單單只是鮮豔，更能讓孩子看到大自然多層次的美，如毛毛蟲身上的綠，絕對不是坊間單一層次的綠所能比擬的。除此之外，艾瑞．卡爾擅長在豐富的童趣中，展現對生命的讚嘆，當毛毛蟲一路吃啊吃、最後蛻變成美麗的蝴蝶時，生命的可貴多麼令人喜悅。正如《遇見圖畫書百年經典》彭懿所說的：「這是一本充滿了詩情與創意的圖畫書。說詩意，你看，綠葉、大地、蝴蝶、五彩繽紛的果實、清輝四射的月亮、炙熱似火的太陽&hellip;&hellip;作者如同一個激情洋溢的詩人，用奔放不羈而又濃烈絢麗的顏色，為孩子們唱出了一首生命的禮讚」。",
