    introduce: "在這本圖畫書裡，祖孫一起做許多的事，他們觀察螞蟻、貓咪、樹木、石頭，也一起經歷孩子間的打鬧、甚至外在環境的許多危險處境。故事中的爺爺把孩子的不安當作很重要的一件事，每當遇到困難、害怕、憂慮的時刻，爺爺並不要求孫子一定要堅強、勇敢，只是溫柔的對他說：「沒關係，沒關係」。這句再平凡不過的話，隱含著無限的愛與包容，也代表著爺爺充滿智慧的理解與陪伴。這種安心的後盾，是成長中最珍貴的力量，讓孩子在面對生命中每個艱困時刻，有了愛的依靠，並從中獲得前進的力量。",
