    introduce: "「要不要」是一位凡事都猶豫不決的孩子，無論是起床、洗臉、吃飯、穿衣服還是工作，他都會思考著要或不要去做，常常就這麼浪費了一天的時間。 一天，村裡發生了大火，「要不要」在猶豫不決中，讓整個村莊化為一片灰燼。因而受到村人責難，「要不要」覺得很內疚對不起村裡的人，於是決定到鄰村找「果斷爺爺」幫忙，希望有智慧的爺爺可以教他一些方法，讓他可以不再徬徨。一路上「要不要」遇到了一些阻礙，所幸化險為夷找到了「果斷爺爺」。",
