    introduce: "一個想像力豐富的小男孩，加上一個什麼都不會的怪怪老師， 會發生什麼超乎想像的校園趣事呢？ 《我的瘋狂學校》本校特色： 1.有不會注音、也不會算術的老師。 2.有答應將學校改建成電動遊樂場的校長。 歡迎報名參觀，體驗不同的校園生活！ 你遇過這樣的老師嗎？ 不會注音，不會算４×４，還總是要同學們教她！ 你遇過這樣的校長嗎？ 竟然答應將學校「租」給學生改建成電動遊樂場， 連老師都舉雙手贊成！ 但條件是，同學們要看完「一百萬頁」的書。 一百萬頁！！聽上去是好多好多本書。 究竟小傑和同學們能不能完成這項挑戰， 實現把學校改建成電動遊樂場的夢想呢？",
