    introduce: "獅子認為，會不會閱讀和寫字一點也不重要！直到他愛上了一隻美麗，而且喜歡看書的母獅子…獅子必須寫一封情書，來表達他的愛意。不過，獅子沒有開始學寫字，反而用他最常用的方法：命令其他的動物幫他寫信。所以猴子、河馬、推糞蟲、長頸鹿、鱷魚和禿鷹，大家輪流拿起筆，絞盡腦汁要寫一封最完美的情書。不過大家寫的信，獅子一點也不滿意，他該怎麼辦呢？很棒的故事，巧妙地搭配上可愛的插畫，讓小朋友了解到除了說話，讀和寫也是很重要的溝通方式，不僅能讓我們更了解彼此，還可以用來談情說愛！",
