    introduce: "兒童文學作家鄭宗弦， 將兒時家中餅鋪在農曆新年期間，藉由製作年糕的回憶融合熟悉的傳統味道，述說團圓的滋味。 插畫家陳奕喬， 細膩刻劃台灣早期日常景物，溫暖呈現80年代的樸實，不管人在哪裡，過年時都要回家團圓。過年時各種應景的年糕更是不可或缺的傳統食物、蘿蔔糕、發糕、甜年糕、鹹甜糕。闔家團圓的農曆新年是我們傳統文化中最重要的節慶之一，年糕暗喻「步步高（糕）升」，豐盛的年夜飯在過去農業生活更是難得的大餐，除夕夜守歲，更包含著對長輩的祈福和親情的凝聚。",
